59	    begin: TEXTIO_READ_IN
60	      $display("### INFO: RTL Simulation of NCO.");
61	      $display("### Testcase %d", `TESTCASE);
62	      $sformat(filename_mat_inp,"%s%0d%s","./sim/testcases/stimuli/stimuli_tc_",`TESTCASE,"_mat.dat");
63	      $sformat(filename_mat_oup,"%s%0d%s","./sim/testcases/response/response_tc_",`TESTCASE,"_mat.dat");
