75		  $fclose(fid_mat_oup); 
76	
77		  if (error_count>0)
78	            $display("### INFO: Testcase FAILED");
79	          else
80	            $display("### INFO: Testcase PASSED");
81		    
82	  	  $finish; 
83		end
84	    end
85	    
86	  always @(posedge s_clk)
87	    begin: MATLAB_STIMULI
88	      if (i_rst_an && i_ena)
89	        status_mat_inp = $fscanf(fid_mat_inp,"%d\n", i_fcw);
90	      else
91	        i_fcw = 'd0;
92		
93	      if ($feof(fid_mat_inp)) begin
94	        data_ready = 1'b1;
95	      end
96	    end
97	  
