117	      begin: TEXTIO_WRITE_OUT 
118	        $sformat(filename_rtl_oup,"%s%0d%s","./sim/testcases/response/response_tc_",`TESTCASE,"_rtl.dat");
119	        fid_rtl_oup = $fopen(filename_rtl_oup, "w");
120	        @(posedge data_ready)  $fclose(fid_rtl_oup);
121	      end
